333	        e.Proveedor.Ok(Texto(prov, "m-visible-solo-en-auditoria", 10, 5));
334	        var r = await e.Cliente.PostAsync(EntornoAuditoria.Url, new StringContent(
335	            JsonSerializer.Serialize(new { pregunta = Pregunta, usuario = new { rol = "estudiante", id = "T-E1" } }),
336	            System.Text.Encoding.UTF8, "application/json"));
