338	        var cuerpo = await r.Content.ReadAsStringAsync();
339	        var campos = JsonDocument.Parse(cuerpo).RootElement.EnumerateObject().Select(p => p.Name).OrderBy(x => x, StringComparer.Ordinal).ToArray();
340	        Assert.Equal(new[] { "citas", "costoUsd", "respuesta", "tokens", "usoDatosEstudiante" }, campos);
341	        Assert.DoesNotContain("m-visible-solo-en-auditoria", cuerpo);
342	        foreach (var h in r.Headers.Concat(r.Content.Headers))
343	        {
344	            Assert.DoesNotContain("model", h.Key, StringComparison.OrdinalIgnoreCase);
345	            Assert.DoesNotContain("m-visible-solo-en-auditoria", string.Join(",", h.Value));
346	        }
347	    }
