147	        Assert.Equal(JsonValueKind.String, l.GetProperty("fechaHora").ValueKind);
148	        var f = DateTimeOffset.Parse(l.GetProperty("fechaHora").GetString()!, System.Globalization.CultureInfo.InvariantCulture);
